import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Equipment from './Equipment';
import EquipmentSearch from './EquipmentSearch';
import styled from 'styled-components';

// Styled components for layout
const Container = styled.div`
  display: flex;
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
`;

const Content = styled.div`
  flex: 3;
`;

const Sidebar = styled.div`
  flex: 1;
  padding: 15px;
  border-left: 1px solid #ddd;
  margin-left: 20px;
  max-height: 600px;
  overflow-y: auto;
  background-color: #f7f9fc;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  border-radius: 8px;
`;

const Modal = styled.div`
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background-color: white;
  padding: 20px;
  z-index: 1000;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
  border-radius: 10px;
  width: 80%;
  max-width: 600px;
  overflow-y: auto;
  max-height: 90vh;
`;

const Overlay = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.7);
  z-index: 999;
`;

const TabButton = styled.button`
  flex: 1;
  padding: 10px;
  cursor: pointer;
  background: #f2f2f2;
  border: none;
  &:hover {
    background: #ddd;
  }
  &.active {
    background: #ddd;
    font-weight: bold;
  }
`;

const EquipmentPage = () => {
  const [equipmentData, setEquipmentData] = useState([]);
  const [selection, setSelection] = useState(() => {
    // Load persisted items from local storage
    const savedItems = localStorage.getItem('selection');
    return savedItems ? JSON.parse(savedItems) : [];
  });
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);
  const [isTabModalOpen, setIsTabModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState('beginner');
  const itemsPerPage = 20;

  // Fetch equipment data from the API
  const fetchData = async (searchTerm = '', category = 'all', minPrice = '', maxPrice = '') => {
    setLoading(true);
    try {
      const response = await axios.get('/api/equipment', {
        params: { page: currentPage, search: searchTerm, category, min_price: minPrice, max_price: maxPrice },
      });
      setEquipmentData(response.data.equipment);
      setTotalPages(response.data.total_pages);
      setLoading(false);
    } catch (error) {
      setError('Failed to load data');
      setLoading(false);
    }
  };

  // Load initial data and selection
  useEffect(() => {
    fetchData();
  }, [currentPage]);

  // Persist selection in local storage when it changes
  useEffect(() => {
    localStorage.setItem('selection', JSON.stringify(selection));
  }, [selection]);

  // Add to selection
  const addToSelection = (item) => {
    setSelection((prevSelection) => [...prevSelection, item]);
  };

  // Remove from selection
  const removeFromSelection = (itemId) => {
    setSelection((prevSelection) => prevSelection.filter((item) => item.id !== itemId));
  };

  // Open and close modals
  const openModal = (item) => {
    setSelectedItem(item);
    setIsModalOpen(true);
  };
  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedItem(null);
  };

  const openTabModal = () => {
    setIsTabModalOpen(true);
  };
  const closeTabModal = () => {
    setIsTabModalOpen(false);
  };

  // Pagination controls
  const nextPage = () => {
    if (currentPage < totalPages) setCurrentPage((prev) => prev + 1);
  };

  const prevPage = () => {
    if (currentPage > 1) setCurrentPage((prev) => prev - 1);
  };

  // Render content based on active tab with detailed tips
  const renderTabContent = () => {
    switch (activeTab) {
      case 'beginner':
        return (
          <div>
            <h3>Beginner Tips</h3>
            <p>If you're new to triathlons, focus on affordable and essential gear to get you started without overwhelming costs:</p>
            <ul>
              <li><strong>Entry-Level Road Bike:</strong> Look for an affordable road bike with basic components (often aluminum frames). Brands like Giant and Trek offer solid, budget-friendly options. This bike doesn’t need to be fancy but should be comfortable for long rides and basic training.</li>
              <li><strong>Standard Helmet & Gloves:</strong> Safety is crucial, so invest in a basic helmet that meets safety standards and gloves for comfort on the handlebars. Avoid high-end gear for now; instead, go for solid brands like Bell or Giro for helmets.</li>
              <li><strong>Swim Goggles & Wetsuit:</strong> Start with comfortable goggles and a beginner wetsuit. A wetsuit designed for buoyancy will help you in open-water training, improving confidence and endurance.</li>
              <li><strong>Running Shoes:</strong> Select a pair of affordable but supportive running shoes suitable for basic training. Visit a store for a gait analysis if possible; brands like Asics or Brooks have solid beginner options.</li>
              <li><strong>Hydration & Basic Nutrition:</strong> Use a simple hydration pack or bottle cage for your bike. Basic energy gels or bars are enough to start getting used to fueling your body during long sessions.</li>
            </ul>
          </div>
        );
      case 'training':
        return (
          <div>
            <h3>Training Tips</h3>
            <p>As you train more frequently, investing in mid-range, durable gear can significantly improve comfort and performance:</p>
            <ul>
              <li><strong>Quality Road Bike:</strong> Upgrade to a bike with robust, lightweight components (consider carbon forks for a smoother ride). Focus on quality gears and a comfortable saddle. Specialized and Cannondale are great brands in this range.</li>
              <li><strong>Running Shoes:</strong> Invest in running shoes with better support and durability, especially for increased mileage. Look for brands like Saucony or Nike with cushioning and stability features.</li>
              <li><strong>GPS Watch:</strong> A reliable GPS watch with tracking and interval features can help monitor your progress. Garmin and Polar offer good models for tracking pace, distance, and heart rate.</li>
              <li><strong>Waterproof Swim Cap & Mid-Tier Wetsuit:</strong> For open water training, a better-fitting, flexible wetsuit will make a noticeable difference in comfort and speed. Look into wetsuits from Orca or Zone3 designed for training.</li>
              <li><strong>Nutrition & Supplements:</strong> Incorporate electrolytes and endurance-friendly supplements like energy gels or powders for training sessions over 90 minutes. Brands like GU or Clif provide reliable options.</li>
            </ul>
          </div>
        );
      case 'race day':
        return (
          <div>
            <h3>Race Day Gear</h3>
            <p>On race day, performance-oriented gear can give you an edge, so focus on lightweight, race-specific equipment:</p>
            <ul>
              <li><strong>Lightweight, Aerodynamic Bike:</strong> If you’re looking for speed, consider an aerodynamic road or triathlon bike. Look for features like deep-section wheels, a lighter frame, and aero bars to reduce drag.</li>
              <li><strong>Race-Specific Running Shoes:</strong> Lighter, responsive shoes designed for racing (like carbon-plated models from Nike or Hoka) can help with speed while maintaining comfort over longer distances.</li>
              <li><strong>Triathlon Suit:</strong> Invest in a race-specific tri-suit designed for comfort across swim, bike, and run segments. Look for moisture-wicking materials and a snug fit for aerodynamics.</li>
              <li><strong>Easy-to-Open Hydration Packs & Gels:</strong> Race-day nutrition should be easy to access and consume, so look for nutrition packs and hydration systems you can open on the move, like those from Hammer Nutrition or Tailwind.</li>
              <li><strong>Polarized Goggles:</strong> These will help reduce glare, especially for open water swimming on sunny days, providing clear visibility and reducing eye strain.</li>
            </ul>
          </div>
        );
      case 'expert':
        return (
          <div>
            <h3>Expert Tips</h3>
            <p>As an experienced athlete, high-end, optimized gear can help you push performance to the limit:</p>
            <ul>
              <li><strong>Carbon Fiber Bike:</strong> Go for a top-tier triathlon bike with a full carbon frame, electronic shifting, and aero enhancements. Consider custom fitting to maximize efficiency. Brands like Cervelo or BMC offer elite-level options.</li>
              <li><strong>Custom Running Shoes:</strong> Elite runners benefit from custom-fit shoes designed to their specific gait, often involving orthotics and specialized materials for lighter weight and better energy return.</li>
              <li><strong>Performance Tri-Suit:</strong> Invest in a tri-suit engineered for aerodynamics and comfort, with materials that reduce drag in water and wick moisture effectively on land. Top brands include HUUB or Roka.</li>
              <li><strong>High-End Wetsuit:</strong> Choose a wetsuit with buoyancy panels and flexible shoulders, designed for optimal swimming speed and minimal resistance. Suits from Orca or Blueseventy are good for this level.</li>
              <li><strong>Advanced Nutrition Strategy:</strong> Work with a sports nutritionist to create a personalized hydration and fueling plan using top-quality gels, drinks, and recovery supplements from brands like SIS or Maurten.</li>
            </ul>
          </div>
        );
      default:
        return null;
    }
  };


  if (loading) return <p>Loading...</p>;
  if (error) return <p>{error}</p>;

  return (
    <Container>
      <Content>
        <button onClick={openTabModal}>Open Tips & Guides</button>
        <EquipmentSearch onSearch={fetchData} />
        <Equipment equipment={equipmentData} onAddToSelection={addToSelection} />

        {/* Pagination */}
        <div style={{ display: 'flex', justifyContent: 'center', marginTop: '10px' }}>
          <button onClick={prevPage} disabled={currentPage === 1}>Previous</button>
          <span style={{ margin: '0 10px' }}>Page {currentPage} of {totalPages}</span>
          <button onClick={nextPage} disabled={currentPage === totalPages}>Next</button>
        </div>
      </Content>

      {/* Sidebar */}
      <Sidebar>
        <h2>Your Selection</h2>
        {selection.length > 0 ? (
          <ul>
          {selection.map((item) => (
            <SidebarItem key={item.id} onClick={() => openModal(item)}>
              <div>
                <strong>{item.name}</strong> - ${item.price || '0.00'}
              </div>
              <button onClick={(e) => { e.stopPropagation(); removeFromSelection(item.id); }}>Remove</button>
            </SidebarItem>
          ))}
        </ul>
        ) : (
          <p>No items added yet.</p>
        )}
        <div>Total: ${selection.reduce((sum, item) => sum + (item.price || 0), 0).toFixed(2)}</div>
      </Sidebar>

      {/* Modal for item details */}
      {isModalOpen && (
        <>
          <Overlay onClick={closeModal} />
          <Modal>
            <h2>{selectedItem?.name}</h2>
            <p>Price: ${selectedItem?.price}</p>
            <p>{selectedItem?.description}</p>
            <button onClick={closeModal}>Close</button>
          </Modal>
        </>
      )}

      {/* Tab modal for detailed tips */}
      {isTabModalOpen && (
        <>
          <Overlay onClick={closeTabModal} />
          <Modal>
            <div style={{ display: 'flex', justifyContent: 'space-around' }}>
              {['beginner', 'training', 'race day', 'expert'].map((tab) => (
                <TabButton
                  key={tab}
                  className={activeTab === tab ? 'active' : ''}
                  onClick={() => setActiveTab(tab)}
                >
                  {tab.charAt(0).toUpperCase() + tab.slice(1)}
                </TabButton>
              ))}
            </div>
            <div>{renderTabContent()}</div>
            <button onClick={closeTabModal}>Close</button>
          </Modal>
        </>
      )}
    </Container>
  );
};

export default EquipmentPage;
